    74  static char *get_partition_search_pattern (const char *partition, const char *topic)
    75  {
    76    size_t sz = strlen (partition) + strlen (topic) + 2;
    77    char *pt = ddsrt_malloc (sz);
    78    (void) snprintf (pt, sz, "%s.%s", partition, topic);
    79    return pt;
    80  }
