    82  const struct ddsi_config_partitionmapping_listelem *find_partitionmapping (const struct ddsi_config *cfg, const char *partition, const char *topic)
    83  {
    84    char *pt = get_partition_search_pattern (partition, topic);
    85    struct ddsi_config_partitionmapping_listelem *pm;
    86    for (pm = cfg->partitionMappings; pm; pm = pm->next)
    87      if (wildcard_wildcard_match (pt, pm->DCPSPartitionTopic))
    88        break;
    89    ddsrt_free (pt);
    90    return pm;
    91  }
