    93  static int ddsi_is_ignored_partition_one (const struct ddsi_config *cfg, const char *partition, const char *topic)
    94  {
    95    char *pt = get_partition_search_pattern (partition, topic);
    96    struct ddsi_config_ignoredpartition_listelem *ip;
    97    for (ip = cfg->ignoredPartitions; ip; ip = ip->next)
    98      if (wildcard_wildcard_match (pt, ip->DCPSPartitionTopic))
    99        break;
   100    ddsrt_free (pt);
   101    return ip != NULL;
   102  }
