   104  static void get_partition_set_from_xqos (char const * const * *ps, uint32_t *nps, const struct dds_qos *xqos)
   105  {
   106    static const char *ps_def = "";
   107    if ((xqos->present & QP_PARTITION) && xqos->partition.n > 0) {
   108      *ps = (char const * const *) xqos->partition.strs;
   109      *nps = xqos->partition.n;
   110    } else {
   111      *ps = &ps_def;
   112      *nps = 1;
   113    }
   114  }
