   116  bool ddsi_is_ignored_partition (const struct ddsi_domaingv *gv, const struct dds_qos *xqos, const char *topic_name)
   117  {
   118    char const * const *ps;
   119    uint32_t nps;
   120    get_partition_set_from_xqos (&ps, &nps, xqos);
   121    for (uint32_t i = 0; i < nps; i++)
   122      if (ddsi_is_ignored_partition_one (&gv->config, ps[i], topic_name))
   123        return true;
   124    return false;
   125  }
