   127  static const struct ddsi_config_networkpartition_listelem *ddsi_get_partition_from_mapping_one (const struct ddsrt_log_cfg *logcfg, const struct ddsi_config *config, const char *partition, const char *topic)
   128  {
   129    const struct ddsi_config_partitionmapping_listelem *pm;
   130    if ((pm = find_partitionmapping (config, partition, topic)) == NULL)
   131      return 0;
   132    else
   133    {
   134      DDS_CLOG (DDS_LC_DISCOVERY, logcfg, "matched writer for topic \"%s\" in partition \"%s\" to networkPartition \"%s\"\n", topic, partition, pm->networkPartition);
   135      return pm->partition;
   136    }
