   153  static void free_config_networkpartition_addresses_one (struct ddsi_config_networkpartition_listelem *np)
   154  {
   155    struct ddsi_networkpartition_address **ps[] = {
   156      &np->uc_addresses,
   157      &np->asm_addresses
   158  #ifdef DDS_HAS_SSM
   159      , &np->ssm_addresses
   160  #endif
   161    };
   162    for (size_t i = 0; i < sizeof (ps) / sizeof (ps[0]); i++)
   163    {
   164      while (*ps[i])
   165      {
   166        struct ddsi_networkpartition_address *x = *ps[i];
   167        *ps[i] = x->next;
   168        ddsrt_free (x);
   169      }
   170    }
   171  }
